package com.orbitstorage.provider.api;

import java.io.InputStream;
import java.io.IOException;
import java.util.Optional;

/** Object keys are generated by OrbitStorage, never supplied by clients. */
public interface StorageProvider extends AutoCloseable {
    void upload(String key, InputStream source, long size, String contentType) throws IOException;
    InputStream download(String key) throws IOException;
    void delete(String key) throws IOException;
    Optional<ObjectMetadata> getMetadata(String key) throws IOException;
    void checkHealth() throws IOException;
    default boolean exists(String key) throws IOException { return getMetadata(key).isPresent(); }
    default Optional<Long> getUsage() { return Optional.empty(); }
    default void close() {}
    record ObjectMetadata(long size) {}
}
